    "reportReviewSupport": "If you have received an assessment report from a clinic or school in Ajman, we review the findings together. We demystify complex percentiles and clinical terminology, explain what the results mean for daily family life, and help you translate clinical recommendations into practical home routines and school accommodation requests.",
    "overseasPakistaniSupport": "For expatriate and overseas Pakistani families living in Ajman, navigating cultural differences, bilingual language development, and unfamiliar school systems can feel overwhelming. We provide culturally fluent guidance in English or Urdu to support your child's developmental well-being and smooth educational adaptation.",
