    "schoolSystemOverview": "In Dammam and throughout the Gulf, international and private schools adhere to robust inclusion standards (such as Dubai's KHDA Inclusive Education Framework and regional Ministry of Education policies for Students of Determination). Schools frequently require formal psychoeducational evaluations and implement Individualized Education Plans (IEPs). We support expatriate and local families in interpreting evaluation requirements, preparing for school inclusion meetings, and managing transitions across educational systems.",
