    "overseasPakistaniSupport": "For expatriate and overseas Pakistani families living in Dammam, navigating cultural differences, bilingual language development, and unfamiliar school systems can feel overwhelming. We provide culturally fluent guidance in English or Urdu to support your child's developmental well-being and smooth educational adaptation.",
