    "serviceScopeStatement": "Services for families in Calgary are strictly limited to online parent guidance, psychological report interpretation, and home behavioural strategies. This service does not include direct therapy or formal psychiatric diagnosis.",
    "crossBorderDisclaimer": "This is an international online parent guidance service. The provider is not locally registered or licensed as an in-person practitioner within Calgary, Canada.",
    "formalDiagnosisDisclaimer": "No formal clinical diagnosis can be provided through this online parent guidance service. Families seeking a formal diagnostic assessment must consult a locally licensed developmental paediatrician or clinical psychologist in Canada.",
    "emergencyServiceDisclaimer": "This service does not provide crisis intervention or emergency mental health services. If your child is in immediate danger, please contact local emergency medical services in Calgary.",
    "seoTitle": "Online Parent Guidance in Calgary | Rabbia Psychologist",
    "metaDescription": "Specialized parent guidance and child development support for families in Calgary, Canada. Practical online telehealth strategies for ADHD, autism, behaviour, and school meetings.",
    "pageHeading": "Online Parent Guidance for Families in Calgary",
    "introductorySummary": "Families in Calgary, Canada, can access structured online parent guidance designed to address attention difficulties, emotional dysregulation, autism spectrum profiles, and school collaboration. Delivered via secure telehealth, our consultations equip parents with evidence-based behavioral routines and report review support from the comfort of home. Services are strictly educational and parent-directed; we do not provide in-person clinical evaluations or formal cross-border diagnoses.",
